import assert from 'node:assert/strict';
import { createController } from './src/controller.js';
const pending = [];
const audits = [], renders = [];
const controller = createController({service:{commit(snapshot){return new Promise((resolve,reject)=>pending.push({snapshot,resolve,reject}));}},audit:{record(value){audits.push(value);}},render(value){renders.push(value);}});
controller.open('old','alice'); controller.edit('first');
const first=controller.submit();
assert.equal(typeof first.then,'function');
controller.edit('second'); const second=controller.submit();
controller.close(); controller.open('new','bob'); controller.edit('third'); const third=controller.submit();
pending[0].resolve({revision:1}); await first;
pending[1].reject(new Error('failed')); await second;
pending[2].resolve({revision:3}); assert.deepEqual(await third,{revision:3});
assert.deepEqual(audits,[{doc:'old',actor:'alice',text:'first',revision:1},{doc:'new',actor:'bob',text:'third',revision:3}]);
assert.deepEqual(renders,[{status:'saved',doc:'new'}]);
controller.close(); assert.equal(await controller.submit(),null);
const errors=[]; const broken=createController({service:{commit(){throw Error('sync');}},audit:{record(){throw Error('unexpected audit');}},render(value){errors.push(value);}});
broken.open('x','y'); assert.equal(await broken.submit(),undefined); assert.deepEqual(errors,[{status:'error',doc:'x'}]);
console.log('controller async checks passed');
EOF
